/* Shared dropdown masters; Vehicle Brands remains the storage key for compatibility. */
function modelKey(make,model){return JSON.stringify([make.trim().toLowerCase(),model.trim().toLowerCase()])}
function addSharedVehicleOption(make,model){make=String(make||'').trim();model=String(model||'').trim();if(!make)return;let brands=db.lists['Vehicle Brands']||(db.lists['Vehicle Brands']=[]);if(!brands.some(v=>v.toLowerCase()===make.toLowerCase()))brands.push(make);db.vehicleModels=db.vehicleModels||[];if(model&&!db.vehicleModels.some(v=>modelKey(v.make,v.model)===modelKey(make,model)))db.vehicleModels.push({make,model});db.lists['Vehicle Models']=db.vehicleModels.map(v=>v.make+' — '+v.model)}
if(!db.vehicleListMigration){db.vehicleModels=db.vehicleModels||[];for(let [make,models]of Object.entries(modelOptions))for(let model of models)addSharedVehicleOption(make,model);for(let b of db.bikes)addSharedVehicleOption(b.brand,b.model);for(let p of db.parts)addSharedVehicleOption(p.vehicleMake,p.vehicleModel);db.vehicleListMigration=true;save()}
partVehicleMakes=function(){return [...db.lists['Vehicle Brands']||[]].sort((a,b)=>a.localeCompare(b))};
partVehicleModels=function(make){return (db.vehicleModels||[]).filter(v=>v.make.toLowerCase()===String(make||'').toLowerCase()).map(v=>v.model).sort((a,b)=>a.localeCompare(b))};
let vehicleRecordSeen=new Map([...db.bikes.map(b=>['bikes|'+b.id,JSON.stringify([b.brand,b.model])]),...db.parts.map(p=>['parts|'+p.id,JSON.stringify([p.vehicleMake,p.vehicleModel])])]);
const saveBeforeSharedLists=save;
save=function(message){let listsBefore=structuredClone(db.lists),modelsBefore=structuredClone(db.vehicleModels||[]),seen=new Map(vehicleRecordSeen);for(let [key,rows]of [['bikes',db.bikes],['parts',db.parts]])for(let r of rows){let make=key==='bikes'?r.brand:r.vehicleMake,model=key==='bikes'?r.model:r.vehicleModel,signature=JSON.stringify([make,model]),id=key+'|'+r.id;if(vehicleRecordSeen.get(id)!==signature){addSharedVehicleOption(make,model);seen.set(id,signature)}}let result=saveBeforeSharedLists(message);if(result===false){db.lists=listsBefore;db.vehicleModels=modelsBefore}else vehicleRecordSeen=seen;return result};
let managedListSearch='',managedModelMake='';
function sharedListLabel(key){return key==='Vehicle Brands'?'Vehicle Make':key}
function commitManagedList(action){let before=structuredClone(db);action();db.lists['Vehicle Models']=(db.vehicleModels||[]).map(v=>v.make+' — '+v.model);audit('List Update',sharedListLabel(listName)+' changed');if(save('Dropdowns saved and synced')===false){db=before;return false}return true}
listsPage=function(){let models=listName==='Vehicle Models',values=models?(db.vehicleModels||[]):db.lists[listName]||[];return `<div class="intro"><h2>Dropdown List Management <span class="badge info">Master Control</span></h2><p>Add, rename or remove dropdown options. Changes save automatically and are used across linked modules.</p></div><div class="listlayout"><div class="listselector">${Object.keys(db.lists).map(key=>`<button class="${key===listName?'active':''}" data-list="${esc(key)}">${esc(sharedListLabel(key))}<span style="float:right">${db.lists[key].length}</span></button>`).join('')}</div><section class="panel"><div class="panelhead"><h2>${esc(sharedListLabel(listName))}</h2><span class="badge">Live Connected</span></div><div class="panelbody"><form id="managedListForm" class="toolbar">${models?`<select id="managedModelMake" required aria-label="Vehicle make for model"><option value="">Select Vehicle Make</option>${opts(partVehicleMakes(),managedModelMake)}</select>`:''}<input name="option" required placeholder="Type new option name" aria-label="New list option"><button class="btn" type="submit">Add Option</button></form><input id="managedListSearch" type="search" aria-label="Search options" placeholder="Search options in this list…" value="${esc(managedListSearch)}"><div id="managedListRows">${values.map((value,i)=>{let text=models?value.make+' — '+value.model:value;return `<div class="listoption" data-list-text="${esc(text.toLowerCase())}" ${text.toLowerCase().includes(managedListSearch.toLowerCase())?'':'hidden'}><span>${esc(text)}</span><div><button type="button" class="btn secondary small" data-managed-rename="${i}" aria-label="Rename ${esc(text)}">${icon('edit')}</button><button type="button" class="btn danger small" data-managed-remove="${i}" aria-label="Remove ${esc(text)}">${icon('trash')}</button></div></div>`}).join('')}</div><p class="notice">Automatic sync: Vehicle Make and linked Models are shared by vehicle registration and spare-part compatibility. New makes/models saved in those records also appear here. Existing saved records retain their values when an option is removed.</p></div></section></div>`};
const renderBeforeSharedLists=render;
render=function(){renderBeforeSharedLists();if(page!=='lists')return;$('#managedListSearch').oninput=e=>{managedListSearch=e.target.value;for(let row of $$('[data-list-text]'))row.hidden=!row.dataset.listText.includes(managedListSearch.toLowerCase())};if($('#managedModelMake'))$('#managedModelMake').onchange=e=>managedModelMake=e.target.value;$('#managedListForm').onsubmit=e=>{e.preventDefault();let value=String(new FormData(e.target).get('option')||'').trim(),models=listName==='Vehicle Models';if(!value)return;let make=$('#managedModelMake')?.value;if(models&&!make)return toast('Select the vehicle make first.');let duplicate=models?(db.vehicleModels||[]).some(v=>modelKey(v.make,v.model)===modelKey(make,value)):(db.lists[listName]||[]).some(v=>v.toLowerCase()===value.toLowerCase());if(duplicate)return toast('This option already exists.');if(commitManagedList(()=>{if(models)addSharedVehicleOption(make,value);else db.lists[listName].push(value)}))render()};for(let button of $$('[data-managed-remove]'))button.onclick=()=>{let index=Number(button.dataset.managedRemove);if(!window.confirm('Remove this dropdown option? Saved records keep their current values.'))return;if(commitManagedList(()=>{if(listName==='Vehicle Models')db.vehicleModels.splice(index,1);else db.lists[listName].splice(index,1)}))render()};for(let button of $$('[data-managed-rename]'))button.onclick=()=>{let index=Number(button.dataset.managedRename),models=listName==='Vehicle Models',old=models?db.vehicleModels[index].model:db.lists[listName][index],next=window.prompt('Rename option',old)?.trim();if(!next||next===old)return;let duplicate=models?db.vehicleModels.some((v,i)=>i!==index&&modelKey(v.make,v.model)===modelKey(db.vehicleModels[index].make,next)):db.lists[listName].some((v,i)=>i!==index&&v.toLowerCase()===next.toLowerCase());if(duplicate)return toast('This option already exists.');if(commitManagedList(()=>{if(models)db.vehicleModels[index].model=next;else{db.lists[listName][index]=next;if(listName==='Vehicle Brands')for(let v of db.vehicleModels||[])if(v.make.toLowerCase()===old.toLowerCase())v.make=next}}))render()}};
document.addEventListener('change',e=>{if(e.target.name!=='model'||!e.target.closest('#recordForm'))return;let make=$('#recordForm [name="brand"]')?.value,model=e.target.value;if(make&&model&&!partVehicleModels(make).includes(model)){let before=structuredClone(db);addSharedVehicleOption(make,model);if(save('Vehicle model synced')===false)db=before}},true);
render();
/* Manual full sync supplements automatic updates. */
function syncAllDropdownLists(){let before=structuredClone(db);try{for(let b of db.bikes)addSharedVehicleOption(b.brand,b.model);for(let p of db.parts)addSharedVehicleOption(p.vehicleMake,p.vehicleModel);for(let [key,values]of Object.entries(db.lists)){if(key==='Vehicle Models')continue;let seen=new Set();db.lists[key]=values.map(v=>String(v).trim()).filter(v=>{let normalized=v.toLowerCase();if(!v||seen.has(normalized))return false;seen.add(normalized);return true})}db.lists['Vehicle Models']=(db.vehicleModels||[]).map(v=>v.make+' — '+v.model);db.lastListSync=new Date().toISOString();audit('Sync All','Dropdown lists saved; make/model values collected from vehicle and spare-part records');if(save('All dropdown lists synced and saved')===false){db=before;return false}return true}catch(err){db=before;toast('Sync could not be saved: '+err.message);return false}}
const listsBeforeManualSync=listsPage;
listsPage=function(){return `<div class="toolbar manualSyncToolbar"><button type="button" class="btn success" id="syncAllDropdownLists">↻ Sync All</button><span>${db.lastListSync?'Last synced: '+esc(uiDateTime(db.lastListSync)):'Automatic sync is active'}</span></div><p class="notice">Sync All saves every dropdown list and collects make/model values from existing records. Previously removed values still used in those records may be added back.</p>`+listsBeforeManualSync()};
const renderBeforeManualSync=render;
render=function(){renderBeforeManualSync();if(page==='lists'&&$('#syncAllDropdownLists'))$('#syncAllDropdownLists').onclick=()=>{if(syncAllDropdownLists())render()}};
render();
/* Inline editing works in embedded browsers that do not show native prompt dialogs. */
function renameManagedOption(index,next){next=String(next||'').trim();if(!next){toast('Enter an option name.');return false}let models=listName==='Vehicle Models',entry=models?db.vehicleModels[index]:db.lists[listName]?.[index];if(entry===undefined)return false;let old=models?entry.model:entry;if(next===old)return true;let duplicate=models?db.vehicleModels.some((v,i)=>i!==index&&modelKey(v.make,v.model)===modelKey(entry.make,next)):db.lists[listName].some((v,i)=>i!==index&&v.toLowerCase()===next.toLowerCase());if(duplicate){toast('This option already exists.');return false}return commitManagedList(()=>{if(models)db.vehicleModels[index].model=next;else{db.lists[listName][index]=next;if(listName==='Vehicle Brands')for(let v of db.vehicleModels||[])if(v.make.toLowerCase()===old.toLowerCase())v.make=next}})}
const renderBeforeInlineListEdit=render;
render=function(){renderBeforeInlineListEdit();if(page!=='lists')return;for(let button of $$('[data-managed-rename]'))button.onclick=()=>{let index=Number(button.dataset.managedRename),models=listName==='Vehicle Models',value=models?db.vehicleModels[index]?.model:db.lists[listName]?.[index],row=button.closest('.listoption');if(value===undefined||!row)return;for(let active of $$('#managedListRows .inlineListEdit'))if(active.closest('.listoption')!==row){active.closest('.listoption').querySelector('span').hidden=false;active.closest('.listoption').children[1].hidden=false;active.remove()}if(row.querySelector('.inlineListEdit'))return;let label=row.querySelector('span'),controls=button.parentElement;label.hidden=true;controls.hidden=true;let form=document.createElement('form');form.className='inlineListEdit';form.innerHTML=`${models?'<span>'+esc(db.vehicleModels[index].make)+' — </span>':''}<input type="text" value="${esc(value)}" required maxlength="150" aria-label="Edit option name"><button type="submit" class="btn small">Save</button><button type="button" class="btn secondary small">Cancel</button>`;row.appendChild(form);const cancel=()=>{form.remove();label.hidden=false;controls.hidden=false;button.focus()};form.querySelector('button[type="button"]').onclick=cancel;form.onsubmit=e=>{e.preventDefault();if(renameManagedOption(index,form.querySelector('input').value))render()};form.querySelector('input').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();cancel()}};form.querySelector('input').focus();form.querySelector('input').select()}};
render();

